import { LinkCard } from "march/ui"

// March'ı öğrenme yolu: her durak bir kart; baş kısmı kocaman bir emoji (lead), sonda okuma süresi (meta)
// bağlantılar vitrinin gerçek sayfalarına gider
const path = [
  { emoji: "🔘", title: "1. Düğme", description: "Beş varyant, yükleniyor durumu", meta: "2 dk", href: "/buttons/button" },
  { emoji: "🎯", title: "2. İkon düğmesi", description: "Erişilebilir ad zorunlu, ipucu bedava", meta: "3 dk", href: "/buttons/icon-button" },
  { emoji: "🃏", title: "3. Kart", description: "Başlık, eylemler, alt bilgi", meta: "4 dk", href: "/data/card" },
]

export function LearnPath() {
  return <div sx={{ flex: "col", gap: 2 }}>
    {path.map((p) => <LinkCard href={p.href} lead={<span sx={{ text: "2xl" }}>{p.emoji}</span>} title={p.title} description={p.description} meta={p.meta} />)}
  </div>
}

import { LinkCard, Grid, SectionLabel } from "march/ui"
import { users, calendar, layers, folder } from "march/icons"

// bir topluluk yönetim panelinin ana sayfası: her bölüm bir kart (ikon karosu, ton, açıklama, sondaki sayı)
// bağlantılar vitrinde o bölümü gösteren bileşen sayfalarına gider
const sections = [
  { icon: users, tone: "primary", title: "Üyeler", description: "Ara, davet et, rolleri yönet", meta: "128", href: "/data/table" },
  { icon: calendar, tone: "success", title: "Etkinlikler", description: "Bu haftanın buluşmaları", meta: "12", href: "/data/timeline" },
  { icon: layers, tone: "warn", title: "Görevler", description: "Gönüllülerin panosu", meta: "7 açık", href: "/data/kanban" },
  { icon: folder, tone: "violet", title: "Belgeler", description: "Tüzük, tutanaklar, afişler", href: "/data/tree" },
] as const

export function AdminHome() {
  return <div sx={{ flex: "col", gap: 2 }}>
    <SectionLabel count={sections.length}>Yönetim</SectionLabel>
    <Grid cols={2}>
      {sections.map((s) => <LinkCard href={s.href} icon={s.icon} tone={s.tone} title={s.title} description={s.description} meta={"meta" in s ? s.meta : undefined} />)}
    </Grid>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { LinkCardLab } from "./LinkCardLab.tsx"

// LinkCardLab'in testleri: kaydedince Testler sekmesinde çalışır (kartlara basılmaz: bağlantılar sayfadan çıkar)
test("kartın tamamı bir bağlantı; class ve data-* bağlantıya gider", () => {
  const s = renderTest(() => <LinkCardLab />)
  const a = s.find("Tablo")?.closest("a")
  expect(a?.classList.contains("lab-table")).toBe(true)
  expect(a?.classList.contains("m-link-card")).toBe(true)
  expect(a?.getAttribute("href")).toContain("table")
  expect(a?.getAttribute("data-kind")).toBe("veri")
})

test("meta ve title canlı", async () => {
  const s = renderTest(() => <LinkCardLab />)
  expect(s.get(".lab-table .m-link-card-meta")?.textContent).toBe("★ 41")
  await s.click("Yıldız ver")
  expect(s.get(".lab-table .m-link-card-meta")?.textContent).toBe("★ 42")
  await s.click("Başlığı değiştir")
  expect(s.sees("Ağaç görünümü")).toBe(true)
})

test("arrow={false} oku çizmez; varsayılan ok süs olarak gizli", () => {
  const s = renderTest(() => <LinkCardLab />)
  expect(s.get(".lab-noarrow .m-link-card-arrow")).toBe(null)
  expect(s.get(".lab-table .m-link-card-arrow")?.getAttribute("aria-hidden")).toBe("true")
  expect(s.get("#agac")?.tagName).toBe("A")
})

test("lead ikon karosunun yerine geçer", () => {
  const s = renderTest(() => <LinkCardLab />)
  expect(s.get(".lab-lead .m-link-card-lead")).not.toBe(null)
  expect(s.get(".lab-lead .m-icon-tile")).toBe(null)
  expect(s.get(".lab-table .m-icon-tile")).not.toBe(null)
})
